def dedupe_events(events):
    if not isinstance(events, (list, tuple)):
        raise ValueError("events must be a list or tuple")
    order = []
    last = {}
    for item in events:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError("each element must be a 2-tuple")
        key, payload = item
        if not isinstance(key, str) or not isinstance(payload, str):
            raise ValueError("key and payload must be str")
        if key not in last:
            order.append(key)
        last[key] = payload
    return [(key, last[key]) for key in order]
```

